INSERT INTO service_requirements(service_id,field_key,label,field_type,required,options,validation_rules,display_order)
SELECT s.id,d.field_key,d.label,d.field_type,d.required,d.options,d.validation_rules,d.display_order
FROM definitions d JOIN service_categories c ON c.category_code=d.category_code JOIN services s ON s.category_id=c.id
ON CONFLICT(service_id,field_key) DO UPDATE SET label=excluded.label,field_type=excluded.field_type,
required=excluded.required,options=excluded.options,validation_rules=excluded.validation_rules,display_order=excluded.display_order;
